pub fn configured_replicas(region_config: &Value) -> u64 {
    region_config
        .get("numReplicas")
        .and_then(Value::as_u64)
        .unwrap_or(0)
}

pub fn total_replicas(region_data: &Value) -> u64 {
    region_data
        .as_object()
        .map(|config| {
            config.values().fold(0u64, |total, value| {
                total.saturating_add(configured_replicas(value))
            })
        })
        .unwrap_or(0)

pub fn region_data_from_deploy(deploy: &Value) -> Result<Option<Value>> {
    if let Some(c) = deploy.dot_get::<Value>("multiRegionConfig")? {
        return Ok(Some(c));
    }

    if let Some(region) = deploy.dot_get::<String>("region")? {
        // Old deployments only have numReplicas and a region field.
        let mut map = Map::new();
        let replicas = deploy.dot_get::<Value>("numReplicas")?.unwrap_or(json!(1));
        map.insert(region, json!({ "numReplicas": replicas }));
        return Ok(Some(Value::Object(map)));
    }

    Ok(None)
}

pub fn region_data_from_deployment_meta(meta: &Value) -> Result<Option<Value>> {
    let Some(deploy) = meta.dot_get::<Value>("serviceManifest.deploy")? else {
        return Ok(None);
    };

    region_data_from_deploy(&deploy)
}

// check that service exists in that environment
let instance = find_service_instance(environment_instances, &service_id);
let service_meta = if let Some(instance) = instance {
    if let Some(latest) = &instance.latest_deployment {
        if let Some(meta) = &latest.meta {
            region_data_from_deployment_meta(meta)?
        } else {
            None
        }
    } else {
        None
    }
} else {
    bail!("Service not found in the environment")
};

Ok((
    service_meta.unwrap_or(Value::Object(Map::new())),
    service_id,
))
